// Generated by `frust create`. AGP 9's built-in Kotlin support means no
// separate `org.jetbrains.kotlin.android` plugin is applied —
// `com.android.application` alone is enough.
//
// This is the full Frust build-mode matrix: debug,
// profile, and release build types; develop/production product flavors with
// per-flavor identity, naming, and keystore signing (mirrors the Flutter
// muxr app's android/app/build.gradle.kts — see
// android/app/keystores/README.md); optional per-ABI splits; version
// plumbing via local.properties; and a `-P`-parameterized cargo-ndk step.
// Every input the Frust CLI passes is a Gradle `-P` project property or a
// `local.properties`/`app/keystores/key.properties` entry — there are no
// additional scaffold placeholders here, only build-time values with
// Kotlin-side defaults, so an Android-Studio-driven build (no CLI) still
// works with sensible defaults.
import java.util.Properties
import java.io.FileInputStream
import java.util.Base64
import com.android.build.api.variant.FilterConfiguration.FilterType.ABI

plugins {
    id("com.android.application")
}

// `local.properties` carries CLI-written version plumbing (never committed);
// optional: an absent file yields empty `Properties` and the defaults below
// apply.
val localProperties = Properties().apply {
    val f = rootProject.file("local.properties")
    if (f.exists()) FileInputStream(f).use { load(it) }
}

// Release signing: android/app/keystores/key.properties (gitignored) locally,
// or *_KEYSTORE_* env vars on CI. See android/app/keystores/README.md. When
// neither is present the develop/production flavors below fall back to the
// debug keystore so `assembleDevelopDebug`/`assembleProductionDebug` (and a
// hand-run `assemble*Release`) keep working on a dev machine without secrets
// — mirrors the Flutter muxr app's rig verbatim (same property/env names, see
// `/muxr/android/app/build.gradle.kts`) so the password-manager keystores
// drop in unchanged. The fallback is loud for a Release build type: see the
// `developSigningIsDebugFallback`/`productionSigningIsDebugFallback` flags and
// the `androidComponents.onVariants` warning below.
val keystoreProperties = Properties().apply {
    val propsFile = rootProject.file("app/keystores/key.properties")
    if (propsFile.exists()) {
        FileInputStream(propsFile).use { load(it) }
    }
}

fun signingValue(propKey: String, envKey: String): String? =
    keystoreProperties.getProperty(propKey) ?: System.getenv(envKey)

// Set when a flavor's signingConfig below falls back to the debug keystore
// (no app/keystores/key.properties or *_KEYSTORE_* env material found) — read
// by the `androidComponents.onVariants` block further down to warn loudly on
// every *Release variant* that ends up debug-signed. Declared before
// `signingConfigs` so the closures below can assign into it.
var developSigningIsDebugFallback = false
var productionSigningIsDebugFallback = false

// Reads a Gradle `-P` project property with a Kotlin-side default, so every
// CLI-driven knob has a working default for Android-Studio-driven builds.
fun prop(name: String, default: String): String =
    (project.findProperty(name) as String?) ?: default

// Version plumbing (Flutter-canonical mechanism, Frust keys). The CLI
// writes `frust.versionName`/`frust.versionCode` into local.properties;
// defaults keep a hand-run Gradle build working.
val versionNameValue = localProperties.getProperty("frust.versionName", "1.0")
val versionCodeValue = localProperties.getProperty("frust.versionCode", "1").toInt()

// ABI selection + split toggle. `frust.targetPlatforms` is a CSV of Android
// ABIs (default single-ABI arm64-v8a, matching `frust run`'s per-device
// build); `frust.splitPerAbi` gates per-ABI APK splits (off by default — a
// universal APK/AAB is produced instead).
val abis = prop("frust.targetPlatforms", "arm64-v8a")
    .split(",").map { it.trim() }.filter { it.isNotEmpty() }
val splitPerAbi = prop("frust.splitPerAbi", "false").toBoolean()

// `--define K=V` values, base64(`K=V;K=V`) so an arbitrary value survives the
// shell/`-P` boundary. Decoded and set as env vars on the cargo-ndk exec below
// so the Rust side's `option_env!("K")` can read them at compile time.
val definesB64 = prop("frust.defines", "")

// Cargo `--features` selected by the CLI per build mode (release-lean plan):
// base64(`feat,feat`), decoded and appended to the cargo-ndk build below as
// `--features <csv>`. The CLI passes `frust/perf-trace` for debug/profile
// (instrumentation compiled IN) and `lean` for release (the log ceiling);
// empty default so an Android-Studio-driven build (no CLI) adds no features.
// Rides a `-P` property — NOT an env var — so a feature flag can never fall
// foul of the release env-drop Known Issue by construction.
val cargoFeaturesB64 = prop("frust.cargoFeatures", "")

android {
    namespace = "com.it.f0x.muxr"
    compileSdk = 36

    buildFeatures {
        // AGP disables resValue generation by default; the flavors below use
        // it to inject per-flavor app_name strings (mirrors the Flutter muxr
        // app's android/app/build.gradle.kts).
        resValues = true
    }

    defaultConfig {
        applicationId = "com.it.f0x.muxr"
        // Frust's :frust-embedding library floor is 26 (Platform-Support
        // Policy, frust docs/DEVELOPMENT.md) - AGP's manifest merger hard-fails
        // on an app min below it.
        minSdk = 26
        targetSdk = 36
        versionCode = versionCodeValue
        versionName = versionNameValue
    }

    signingConfigs {
        create("develop") {
            val storePath = signingValue("develop.storeFile", "DEVELOP_KEYSTORE_PATH")
            if (storePath != null) {
                storeFile = file(storePath)
                storePassword = signingValue("develop.storePassword", "DEVELOP_STORE_PASSWORD")
                keyAlias = signingValue("develop.keyAlias", "DEVELOP_KEY_ALIAS")
                keyPassword = signingValue("develop.keyPassword", "DEVELOP_KEY_PASSWORD")
            } else {
                initWith(getByName("debug"))
                developSigningIsDebugFallback = true
            }
        }
        create("production") {
            val storePath = signingValue("prod.storeFile", "KEYSTORE_PATH")
            if (storePath != null) {
                storeFile = file(storePath)
                storePassword = signingValue("prod.storePassword", "STORE_PASSWORD")
                keyAlias = signingValue("prod.keyAlias", "KEY_ALIAS")
                keyPassword = signingValue("prod.keyPassword", "KEY_PASSWORD")
            } else {
                initWith(getByName("debug"))
                productionSigningIsDebugFallback = true
            }
        }
    }

    flavorDimensions += "env"

    productFlavors {
        create("develop") {
            dimension = "env"
            applicationIdSuffix = ".dev"
            resValue("string", "app_name", "Muxr Dev")
            signingConfig = signingConfigs.getByName("develop")
        }
        create("production") {
            dimension = "env"
            resValue("string", "app_name", "Muxr")
            signingConfig = signingConfigs.getByName("production")
        }
    }

    buildTypes {
        debug {
            // Sign debug builds with the develop keystore too (falls back to
            // the debug keystore when no key.properties/env is present) so
            // debug and release installs of a flavor never hit on-device
            // signature conflicts (INSTALL_FAILED_UPDATE_INCOMPATIBLE).
            signingConfig = signingConfigs.getByName("develop")
        }
        getByName("release") {
            // Release signing comes from the flavor's signingConfig above
            // (develop/production — build-type signing would win, so none is
            // set here). Neither flavor's keystore configured (no
            // android/app/keystores/key.properties, no env vars)? Both fall
            // back to the debug keystore (see signingConfigs above), so an
            // unsigned local `assemble*Release` still succeeds, but loudly:
            // `androidComponents.onVariants` below logs a warning per
            // debug-signed release variant. Create
            // android/app/keystores/key.properties for real release signing
            // — see android/app/keystores/README.md.
            //
            // R8 + resource shrink: the Kotlin/Java side is
            // small (this app's `MainActivity` plus the `:frust-embedding`
            // module) so the dex win is modest, but shipping unminified
            // release code is not the
            // Frust default. `proguard-rules.pro` carries the two keep
            // rules R8 needs beyond AGP's own default rule set (JNI-bound
            // classes it can't otherwise prove are live) — see that file's
            // comments.
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "proguard-rules.pro",
            )
        }
        // Profile: release codegen with a debug-signed, non-debuggable package
        // for on-device performance measurement. Its cargo profile
        // (`--profile profile`) keeps symbols/tracing on — see cargoNdkBuild.
        // `initWith(release)` copies every build-type property, including
        // `isMinifyEnabled`/`isShrinkResources`/`proguardFiles` above, so
        // profile stays representative of release's minified/shrunk shape —
        // no separate opt-in needed here.
        create("profile") {
            initWith(getByName("release"))
            signingConfig = signingConfigs.getByName("debug")
            matchingFallbacks += listOf("release", "debug")
            isDebuggable = false
        }
        // `debug` is implicit (AGP-provided); overridden above to sign with
        // the develop config — no minification, so no keep-rule risk while
        // iterating.
    }

    // Per-ABI APK splits, off by default. When enabled, one APK per ABI is
    // produced instead of a universal APK.
    splits {
        abi {
            isEnable = splitPerAbi
            reset()
            include(*abis.toTypedArray())
            isUniversalApk = false
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
}

// Frust's Android embedding: the Kotlin host (`FrustActivity`,
// `FrustSurfaceView`, `FrustViewHost`, the vendored accesskit delegate) this
// app's `MainActivity` extends, plus the JNI declarations the Rust side
// exports against. Included by path — see `settings.gradle.kts` and
// `gradle.properties`' `frust.embedding.dir`.
//
// `androidx.core` (edge-to-edge, inset merging, bar-icon contrast) and
// `androidx.activity` (`ComponentActivity`, `onBackPressedDispatcher`) are
// re-exported transitively by the module's `api` declarations, so this app
// declares neither directly.
dependencies {
    implementation(project(":frust-embedding"))
    // frust:plugin-dependencies — plugin-contributed dependencies go below.
    implementation(project(":frust-camera"))
    implementation(project(":frust-secure-storage"))
}

// Per-ABI versionCode offsets, applied only when splits are enabled so each
// split APK gets a distinct, monotonic versionCode. Mapping and formula are the
// official Android docs' "Configure multiple APKs" example
// (developer.android.com/build/configure-apk-splits#configure-APK-versions):
// armeabi-v7a→1, arm64-v8a→2, x86→3, x86_64→4, code = abiCode * 1000 + base.
// (The Flutter-lore mapping is a different set — this is the documented one.)
androidComponents {
    onVariants { variant ->
        if (splitPerAbi) {
            val abiCodes = mapOf(
                "armeabi-v7a" to 1,
                "arm64-v8a" to 2,
                "x86" to 3,
                "x86_64" to 4,
            )
            variant.outputs.forEach { output ->
                val abiName = output.filters.find { it.filterType == ABI }?.identifier
                if (abiName != null) {
                    val abiCode = abiCodes[abiName] ?: 0
                    output.versionCode.set(abiCode * 1000 + versionCodeValue)
                }
            }
        }

        // Loud debug-signing fallback: only the `release` build type ships,
        // so only it warns — `debug`/`profile` sign with `develop`/`debug`
        // deliberately (see the signingConfigs/buildTypes comments above) and
        // must stay silent here.
        //
        // `onVariants` configures EVERY variant on EVERY invocation — AGP
        // computes the whole variant model up front regardless of which task
        // was requested, so `logger.warn` called directly in this block would
        // fire for e.g. `productionRelease` even when only
        // `assembleDevelopDebug` was requested. Instead this hooks `doFirst`
        // onto every release-artifact entry point for the variant: the
        // stable, documented AGP task-naming convention gives us
        // `assemble<Variant>` (APK), `bundle<Variant>` (the AAB — the Play
        // artifact; the Frust CLI's own `appbundle` artifact maps to
        // `bundle<Flavor><Mode>`), and `package<Variant>*` (the packaging
        // tasks, including `package<Variant>Bundle` which backs the AAB).
        // `bundle`/`package` do NOT depend on `assemble`, so a bare
        // `./gradlew :app:bundleProductionRelease` would otherwise silently
        // ship a debug-signed AAB — hooking all three covers every direct
        // invocation, the bare `assemble`/`bundle`/`build` aggregates, and an
        // IDE run configuration. If more than one of these tasks runs in the
        // same invocation (e.g. `bundle` also triggers its `package*Bundle`
        // task), the warning prints once per task that actually runs — a
        // couple of repeated lines in that case, which reads as emphasis
        // rather than spam.
        if (variant.buildType == "release") {
            // Unknown flavor name (a future flavor not yet wired into the
            // `when` above) defaults to `true` — fail loud rather than
            // silently skip the tripwire until that flavor's signing is
            // wired up here.
            val isDebugFallback = when (variant.flavorName) {
                "develop" -> developSigningIsDebugFallback
                "production" -> productionSigningIsDebugFallback
                else -> true
            }
            if (isDebugFallback) {
                val variantNameCapitalized = variant.name.replaceFirstChar { it.uppercase() }
                val assembleTaskName = "assemble$variantNameCapitalized"
                val bundleTaskName = "bundle$variantNameCapitalized"
                val packageTaskPrefix = "package$variantNameCapitalized"
                tasks.matching {
                    it.name == assembleTaskName ||
                        it.name == bundleTaskName ||
                        it.name.startsWith(packageTaskPrefix)
                }.configureEach {
                    doFirst {
                        logger.warn(
                            "[muxr] release variant ${variant.name} is DEBUG-SIGNED: no " +
                                "app/keystores/key.properties or *_KEYSTORE_* env signing " +
                                "material found",
                        )
                    }
                }
            }
        }
    }
}

// Builds the Rust `.so`(s) via `cargo ndk` before every Gradle build.
// `workingDir` is the Rust app root (two levels up from `android/app/`); `-o`
// points at this module's `jniLibs` so the resulting
// `<abi>/libmuxr.so` lands where Gradle packages native
// libraries from automatically.
//
// The cargo profile is chosen from the invoked task names (debug → `build`,
// profile → `build --profile profile`, release → `build --release`) so the
// single `cargoNdkBuild` task hooked into `preBuild` produces the right
// artifact for whichever variant is being assembled. Targets come from
// `frust.targetPlatforms` (repeated `-t <abi>`), defaulting to arm64-v8a —
// the same single-ABI debug build `frust run` has always produced.
//
// `frust run`/`frust build` run their own preflight (Rust target,
// cargo-ndk, JDK, adb); this task assumes the toolchain is on `PATH` and fails
// loudly (inherited from the shell) if it isn't.
val cargoProfileArgs: List<String> = run {
    val requested = gradle.startParameter.taskNames.joinToString(" ").lowercase()
    when {
        requested.contains("release") -> listOf("build", "--release")
        requested.contains("profile") -> listOf("build", "--profile", "profile")
        else -> listOf("build")
    }
}
val cargoTargetArgs: List<String> = abis.flatMap { listOf("-t", it) }

// Decode the base64 `--features` CSV (empty → no extra features).
val cargoFeatureArgs: List<String> =
    if (cargoFeaturesB64.isEmpty()) {
        emptyList()
    } else {
        listOf("--features", String(Base64.getDecoder().decode(cargoFeaturesB64)))
    }

val cargoNdkBuild = tasks.register<Exec>("cargoNdkBuild") {
    workingDir = file("../..")
    commandLine(
        buildList {
            add("cargo")
            add("ndk")
            addAll(cargoTargetArgs)
            add("-o")
            add(file("src/main/jniLibs").absolutePath)
            addAll(cargoProfileArgs)
            addAll(cargoFeatureArgs)
        },
    )
    // Thread `--define`s through as env vars so `option_env!("K")` sees them.
    if (definesB64.isNotEmpty()) {
        String(Base64.getDecoder().decode(definesB64))
            .split(";")
            .filter { it.isNotEmpty() }
            .forEach { kv ->
                val idx = kv.indexOf('=')
                if (idx > 0) environment(kv.substring(0, idx), kv.substring(idx + 1))
            }
    }
}

tasks.named("preBuild") {
    dependsOn(cargoNdkBuild)
}